changeSet.sql:
ALTER TABLE work_order_category ADD COLUMN IF NOT EXISTS default_estimated_duration DOUBLE PRECISION;
UPDATE work_order_category
    SET default_estimated_duration = default_estimated_duration_minutes / 60.0
    WHERE default_estimated_duration_minutes IS NOT NULL;
ALTER TABLE work_order_category DROP COLUMN IF EXISTS default_estimated_duration_minutes;

changeSet.rollback:
ALTER TABLE work_order_category ADD COLUMN IF NOT EXISTS default_estimated_duration_minutes INT;
UPDATE work_order_category
    SET default_estimated_duration_minutes = CAST(default_estimated_duration * 60 AS INT)
    WHERE default_estimated_duration IS NOT NULL;
ALTER TABLE work_order_category DROP COLUMN IF EXISTS default_estimated_duration;
